      "basis": "note",
      "source_refs": ["S1"],
      "supported": true
    },
    {
      "text": "与提示词的关系：提示词只是上下文的一部分，不是全部 [S1]。",
      "basis": "note",
      "source_refs": ["S1"],
      "supported": true
